#!/usr/bin/env node
// Generate the distribution surfaces from the shared source of truth.
//
// Source of truth (edit these):
//   - skills/<name>/SKILL.md   portable Agent Skills (consumed by Claude Code directly)
//   - references/*.md          grounded reference docs the skills cite
//   - agents/<name>.agent.md   agent definitions (Claude Code + Copilot CLI plugin)
//   - AGENTS.md                durable rules
//
// Generated (do not edit by hand):
//   - skills/<name>/references/*.md       the references each skill cites (transitively), copied
//                                          into the skill so it is self-contained once installed
//   - .github/skills/<name>/SKILL.md      copy of each skill for Copilot discovery
//   - .github/agents/<name>.agent.md      repository-level Copilot custom agents
//   - .github/copilot-instructions.md     pointer to AGENTS.md
//   - hooks.json, .github/hooks/vela.json, .github/copilot/settings.json  Copilot hook configs embedding hooks/bin/*.sh
//   - the coverage table in evals/README.md (from each scenario's skills_exercised)
//
// Run:  node scripts/sync-copilot.mjs

import { promises as fs } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const GENERATED_BANNER =
  "<!-- GENERATED by scripts/sync-copilot.mjs from the repo source of truth. Do not edit by hand. -->\n\n";

async function rmrf(p) {
  await fs.rm(p, { recursive: true, force: true });
}

const REF_BANNER = (f) =>
  `<!-- GENERATED copy of references/${f} by scripts/sync-copilot.mjs. Edit the source file, not this copy. -->\n\n`;

// Reference files a markdown text cites, as `references/x.md` or a bare `x.md` that exists in references/.
function citedRefs(md, known) {
  const found = new Set();
  for (const m of md.matchAll(/(?:references\/)?([a-z0-9-]+\.md)/g)) if (known.has(m[1])) found.add(m[1]);
  return found;
}

async function bundleReferences() {
  const refDir = path.join(root, "references");
  const known = new Set((await fs.readdir(refDir)).filter((f) => f.endsWith(".md")));
  const refText = new Map();
  for (const f of known) refText.set(f, await fs.readFile(path.join(refDir, f), "utf8"));

  const skillsDir = path.join(root, "skills");
  let copies = 0;
  for (const e of await fs.readdir(skillsDir, { withFileTypes: true })) {
    if (!e.isDirectory()) continue;
    const skill = path.join(skillsDir, e.name);
    const dst = path.join(skill, "references");
    await rmrf(dst);
    // Transitive closure: a cited reference may itself cite others.
    const need = citedRefs(await fs.readFile(path.join(skill, "SKILL.md"), "utf8"), known);
    for (const f of need) for (const g of citedRefs(refText.get(f), known)) need.add(g);
    if (!need.size) continue;
    await fs.mkdir(dst, { recursive: true });
    for (const f of [...need].sort()) {
      await fs.writeFile(path.join(dst, f), REF_BANNER(f) + refText.get(f));
      copies++;
    }
  }
  return copies;
}

async function copySkills() {
  const src = path.join(root, "skills");
  const dst = path.join(root, ".github", "skills");
  await rmrf(dst);
  const entries = await fs.readdir(src, { withFileTypes: true });
  let count = 0;
  for (const e of entries) {
    if (!e.isDirectory()) continue;
    await fs.cp(path.join(src, e.name), path.join(dst, e.name), { recursive: true });
    count++;
  }
  return count;
}

function frontmatter(md) {
  const m = md.match(/^---\n([\s\S]*?)\n---\n?/);
  if (!m) return { attrs: {}, body: md };
  const attrs = {};
  for (const line of m[1].split("\n")) {
    const kv = line.match(/^([A-Za-z0-9_-]+):\s*(.*)$/);
    if (kv) attrs[kv[1]] = kv[2].trim();
  }
  return { attrs, body: md.slice(m[0].length) };
}

// Repository-level custom agents (.github/agents/*.agent.md) for Copilot (cloud agent, VS Code).
// The source agents/*.agent.md are already loaded as-is by Claude Code and by a Copilot CLI plugin;
// their Claude tool names (Bash, Read, Edit, Write, Grep, Glob) are documented Copilot aliases and
// unknown names (Skill, Agent) are ignored by Copilot. The frontmatter must stay first in the file,
// so the generated banner goes after it.
async function genAgents() {
  const src = path.join(root, "agents");
  const dst = path.join(root, ".github", "agents");
  await rmrf(dst);
  await fs.mkdir(dst, { recursive: true });
  const files = (await fs.readdir(src)).filter((f) => f.endsWith(".agent.md"));
  for (const f of files) {
    const md = await fs.readFile(path.join(src, f), "utf8");
    const { attrs, body } = frontmatter(md);
    const name = attrs.name || path.basename(f, ".agent.md");
    const fm = [`name: ${name}`, `description: ${JSON.stringify(attrs.description || "")}`];
    if (attrs.tools) fm.push(`tools: [${attrs.tools.split(",").map((t) => JSON.stringify(t.trim())).join(", ")}]`);
    const out = `---\n${fm.join("\n")}\n---\n` + GENERATED_BANNER + skillPaths(body.trimStart());
    await fs.writeFile(path.join(dst, `${name}.agent.md`), out);
  }
  return files.length;
}

// Copilot preloads no skill and, given a skill name, tends to grep it (eval runs 2026-11-23): each step of the
// operating loop gets the path of the skill file to read whole.
function skillPaths(body) {
  const step = /^(\d+)\. \*\*([^*]+)\*\*[^\n]*?`((?:using-)?vela-[a-z-]+|using-vela)`/gm;
  const rows = [...body.matchAll(step)].map((m) => `- step ${m[1]} (${m[2]}): \`.github/skills/${m[3]}/SKILL.md\``);
  if (!rows.length) {
    // The reviewer's only skill: Copilot preloads none.
    const one = body.match(/`(vela-[a-z-]+)` \(preloaded\)/);
    return one ? body.replace(one[0], `\`${one[1]}\` (read \`.github/skills/${one[1]}/SKILL.md\` whole first - Copilot preloads no skill)`) : body;
  }
  const note = "\n## Skill files (Copilot)\n\nNo skill is preloaded here. Read `.github/skills/using-vela/SKILL.md` first, then, " +
    "before each step, its skill file **whole** with the read tool - no grep, `head` or line range:\n" + rows.join("\n") + "\n";
  return body.replace(/\n## Operating loop\n/, note + "\n## Operating loop\n");
}

async function genInstructions() {
  const agents = await fs.readFile(path.join(root, "AGENTS.md"), "utf8");
  const out =
    GENERATED_BANNER +
    "# Copilot instructions for Vela\n\n" +
    "These are generated from `AGENTS.md`. Edit `AGENTS.md`, then run " +
    "`node scripts/sync-copilot.mjs`.\n\n" +
    agents;
  const dst = path.join(root, ".github", "copilot-instructions.md");
  await fs.mkdir(path.dirname(dst), { recursive: true });
  await fs.writeFile(dst, out);
}

// Copilot does not document how a hook script path is resolved (plugin dir? cwd?), and a hook that
// exits non-zero (e.g. script not found) DENIES every tool call. So the Copilot configs embed the
// scripts themselves (base64 of hooks/bin/*.sh) instead of pointing at a path. bash: decodes with base64
// (fails closed and loud if it cannot); powershell (Windows): decodes natively and runs it with the bash of
// Git for Windows - without one it warns and allows (a guard that denied every tool would block the agent).
async function genHooks() {
  const embed = async (file, label, arg) => {
    const b64 = (await fs.readFile(path.join(root, "hooks", "bin", file))).toString("base64");
    return {
      bash:
        `g="$(printf %s '${b64}' | base64 -d 2>/dev/null || printf %s '${b64}' | base64 -D 2>/dev/null)"; ` +
        `[ -n "$g" ] || { echo 'vela ${label}: cannot decode the embedded script (base64 missing?)' >&2; exit 2; }; ` +
        `sh -c "$g" vela-${label} ${arg}`,
      powershell:
        `$g = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('${b64}')); ` +
        `if (-not (Get-Command bash -ErrorAction SilentlyContinue)) { [Console]::Error.WriteLine('vela ${label}: bash not found (install Git for Windows) - not checked'); exit 0 }; ` +
        `[Console]::In.ReadToEnd() | bash -c $g vela-${label} ${arg}; exit $LASTEXITCODE`,
    };
  };
  const verified = (await fs.readFile(path.join(root, "references", "cli-surface.md"), "utf8"))
    .match(/Verified against:\*\* `vela (\d+\.\d+\.\d+)/)[1];
  const hooksList = {
    preToolUse: [{ type: "command", ...(await embed("guard.sh", "guard", "cp")), timeoutSec: 10 }],
    sessionStart: [{ type: "command", ...(await embed("session.sh", "session", verified)), timeoutSec: 10 }],
  };
  const config = (where) => ({
    _generated: `by scripts/sync-copilot.mjs from hooks/bin/*.sh (${where}) - do not edit by hand`,
    version: 1,
    hooks: hooksList,
  });
  const write = async (rel, where) => {
    const dst = path.join(root, rel);
    await fs.mkdir(path.dirname(dst), { recursive: true });
    await fs.writeFile(dst, JSON.stringify(config(where), null, 2) + "\n");
  };
  await write("hooks.json", "Copilot CLI plugin");
  await write(path.join(".github", "hooks", "vela.json"), "repository hooks");
  // Copilot CLI 1.0.91 (verified live) does not load .github/hooks/*.json; it loads repo hooks from the
  // `hooks` key of .github/copilot/settings.json - and only in a trusted folder.
  const settings = {
    _generated: "by scripts/sync-copilot.mjs from hooks/bin/*.sh (Copilot CLI repo settings) - do not edit by hand",
    hooks: config("").hooks,
  };
  const dst = path.join(root, ".github", "copilot", "settings.json");
  await fs.mkdir(path.dirname(dst), { recursive: true });
  await fs.writeFile(dst, JSON.stringify(settings, null, 2) + "\n");
}

// Coverage matrix (skill x scenario) from each scenario's skills_exercised, into evals/README.md.
async function genEvalCoverage() {
  const skills = (await fs.readdir(path.join(root, "skills"), { withFileTypes: true }))
    .filter((e) => e.isDirectory()).map((e) => e.name).sort();
  const dir = path.join(root, "evals", "scenarios");
  const scen = [];
  for (const f of (await fs.readdir(dir)).filter((f) => f.endsWith(".md")).sort()) {
    const { attrs } = frontmatter(await fs.readFile(path.join(dir, f), "utf8"));
    const ex = (attrs.skills_exercised || "").replace(/^\[|\]$/g, "").split(",").map((x) => x.trim()).filter(Boolean);
    scen.push({ name: path.basename(f, ".md"), ex: new Set(ex) });
  }
  const rows = skills.map((s) => {
    const hits = scen.filter((c) => c.ex.has(s)).map((c) => c.name);
    return `| \`${s}\` | ${hits.length ? hits.join(", ") : "**none**"} |`;
  });
  const table = ["| Skill | Exercised by |", "| --- | --- |", ...rows].join("\n");
  const readme = path.join(root, "evals", "README.md");
  const md = await fs.readFile(readme, "utf8");
  const out = md.replace(/<!-- coverage:start -->[\s\S]*<!-- coverage:end -->/, `<!-- coverage:start -->\n${table}\n<!-- coverage:end -->`);
  await fs.writeFile(readme, out);
}

// Pass rate per scenario, from that scenario's latest campaign (runs with campaign: + run: k/N), into
// evals/README.md. A scenario re-run after a fix gets a newer campaign; the others keep theirs.
async function genPassRate() {
  const dir = path.join(root, "evals", "runs");
  const runs = [];
  for (const f of (await fs.readdir(dir)).filter((f) => f.endsWith(".md") && f !== "README.md")) {
    const { attrs } = frontmatter(await fs.readFile(path.join(dir, f), "utf8"));
    if (attrs.campaign) runs.push(attrs);
  }
  let table = "_No campaign recorded yet._";
  if (runs.length) {
    const latest = new Map();
    for (const r of runs) if (!latest.has(r.scenario) || r.campaign > latest.get(r.scenario)) latest.set(r.scenario, r.campaign);
    const by = new Map();
    for (const r of runs.filter((r) => r.campaign === latest.get(r.scenario))) {
      const k = r.scenario;
      if (!by.has(k)) by.set(k, { n: 0, pass: 0, checks: 0, grader: 0 });
      const e = by.get(k);
      e.n++; if (r.verdict === "pass") e.pass++; if (r.checks === "pass") e.checks++; if (r.grader === "pass") e.grader++;
    }
    const rows = [...by.entries()].sort().map(([k, e]) =>
      `| \`${k}\` | ${latest.get(k)} | **${e.pass}/${e.n}** | ${e.checks}/${e.n} | ${e.grader}/${e.n} | ${e.pass === e.n ? "ready" : "not ready"} |`);
    const tot = [...by.values()].reduce((a, e) => [a[0] + e.pass, a[1] + e.n], [0, 0]);
    table = [`Latest campaign per scenario - ${tot[0]}/${tot[1]} runs pass.`, "",
      "| Scenario | Campaign | Runs passed | Checks | Grader | Status |", "| --- | --- | --- | --- | --- | --- |", ...rows].join("\n");
  }
  const readme = path.join(root, "evals", "README.md");
  const md = await fs.readFile(readme, "utf8");
  await fs.writeFile(readme, md.replace(/<!-- passrate:start -->[\s\S]*<!-- passrate:end -->/, `<!-- passrate:start -->\n${table}\n<!-- passrate:end -->`));
}

await genEvalCoverage();
await genPassRate();
const refs = await bundleReferences();
const skills = await copySkills();
const modes = await genAgents();
await genInstructions();
await genHooks();
console.log(
  `Bundled ${refs} reference cop(ies) into skills. Synced Copilot surface: ${skills} skill(s), ${modes} custom agent(s), 1 instructions file, 3 hooks files.`,
);
